arguments.file_text:
@using sv_fe21bd402178482a8b3d27214b8569b9.Services

<div class="message-item @(IsHighlighted ? "highlighted" : "")"
     @onmouseenter="() => showActions = true"
     @onmouseleave="() => { showActions = false; showEmojiPicker = false; }">
    <div class="message-avatar">@Message.Author[0]</div>
    <div class="message-body">
        <div class="message-header">
            <span class="message-author">@Message.Author</span>
            <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
        </div>
        <div class="message-content">@Message.Content</div>

        @if (Message.Reactions.Count > 0)
        {
            <div class="reaction-bar">
                @foreach (var reaction in Message.Reactions)
                {
                    <button class="reaction-badge" @onclick="() => HandleReaction(reaction.Emoji)"
                            title="@string.Join(", ", reaction.Users)">
                        <span>@reaction.Emoji</span>
                        <span class="reaction-count">@reaction.Users.Count</span>
                    </button>
                }
            </div>
        }

        @if (ReplyCount > 0)
        {
            <button class="thread-link" @onclick="HandleOpenThread">
                @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
            </button>
        }
    </div>

    @if (showActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="HandleOpenThread" title="Reply in thread">💬</button>
            <button class="action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">😀</button>
        </div>
    }

    @if (showEmojiPicker)
    {
        <div class="emoji-picker">
            @foreach (var emoji in commonEmojis)
            {
