@using sv_fe21bd402178482a8b3d27214b8569b9.Services

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="area-header">
            <h2># @Channel.Name</h2>
            <span class="area-description">@Channel.Description</span>
        </div>

        <div class="message-list" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages…</div>
            }
            @if (HasMoreMessages)
            {
                <button class="load-more-btn" @onclick="OnLoadMore" disabled="@IsLoadingMore">
                    Load older messages
                </button>
            }
            @foreach (var msg in Messages)
            {
                <MessageItem Message="msg"
                             ReplyCount="GetReplyCount(msg.Id)"
                             IsHighlighted="msg.Id == HighlightedMessageId"
                             OnOpenThread="OnOpenThread"
                             OnReaction="OnReaction" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonLabel="Send"
                      OnSend="OnSendMessage" />
    }
