toolArgs.file_text:
.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #313338;
    overflow: hidden;
}

.area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #f2f3f5;
}

.area-description {
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #72767d;
    font-size: 0.85rem;
}

.load-more-btn {
    align-self: center;
    background: none;
    border: 1px solid #3f4147;
    color: #b5bac1;
    padding: 6px 16px;
    border-radius: 6px;
    font-size: 0.8rem;
    cursor: pointer;
    margin: 8px 0;
    transition: background-color 0.15s;
}

.load-more-btn:hover:not(:disabled) {
    background-color: rgba(255, 255, 255, 0.06);
}

.load-more-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.no-channel {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #72767d;
    font-size: 1.1rem;
}

