toolArgs.file_text:
@using sv_fe21bd402178482a8b3d27214b8569b9.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <div class="root-avatar">@RootMessage.Author[0]</div>
            <div class="root-body">
                <span class="root-author">@RootMessage.Author</span>
                <p class="root-content">@RootMessage.Content</p>
            </div>
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply"
                             ReplyCount="0"
                             OnOpenThread="@(_ => { })"
                             OnReaction="OnReaction" />
            }
        </div>

        <MessageInput Placeholder="Reply…"
                      ButtonLabel="Reply"
                      OnSend="OnSendReply" />
    }
</div>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReaction { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #2b2d31;
    border-left: 1px solid #1e1f22;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #f2f3f5;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
    transition: background-color 0.15s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.thread-root-message {
    display: flex;
    gap: 10px;
    padding: 12px 16px;
    background-color: rgba(0, 0, 0, 0.12);
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.root-avatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background-color: #5865f2;
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 0.8rem;
    flex-shrink: 0;
    text-transform: uppercase;
}

.root-body {
    min-width: 0;
}

.root-author {
    font-weight: 600;
    font-size: 0.85rem;
    color: #fff;
}

.root-content {
    font-size: 0.85rem;
    color: #b5bac1;
    margin: 2px 0 0;
    line-height: 1.35;
    word-wrap: break-word;
}

.thread-divider {
    display: flex;
    align-items: center;
    padding: 8px 16px;
    flex-shrink: 0;
}

.thread-divider span {
    font-size: 0.75rem;
    color: #72767d;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

