@page "/chat"
@layout ChatLayout
@using sv_fe21bd402178482a8b3d27214b8569b9.Services
@using sv_fe21bd402178482a8b3d27214b8569b9.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="selectedChannel?.Id"
                        OnChannelSelected="HandleChannelSelected" />
    </div>

    <div class="chat-main @(threadRootMessage is null ? "full-width" : "")">
        <MessageArea Channel="selectedChannel"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     HighlightedMessageId="threadRootMessage?.Id"
                     HasMoreMessages="hasMoreMessages"
                     IsLoadingMore="isLoadingMore"
                     OnLoadMore="LoadOlderMessages"
                     OnSendMessage="HandleSendMessage"
                     OnOpenThread="HandleOpenThread"
                     OnReaction="HandleReaction" />
    </div>

    @if (threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="HandleCloseThread"
                         OnSendReply="HandleSendReply"
                         OnReaction="HandleReaction" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];
    private bool hasMoreMessages;
    private bool isLoadingMore;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await HandleChannelSelected(channels[0]);
        }
    }

    private async Task HandleChannelSelected(Channel channel)
    {
        selectedChannel = channel;
        threadRootMessage = null;
        threadReplies = [];
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        hasMoreMessages = messages.Count >= PageSize;
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to update unread counts
        channels = await ChatService.GetChannelsAsync();

        BuildThreadSummaries();
    }

    private async Task LoadOlderMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        hasMoreMessages = older.Count >= PageSize;

        // Prepend older messages
        messages = [..older, ..messages];
        isLoadingMore = false;

        BuildThreadSummaries();
    }

    private async Task HandleSendMessage(string content)
    {
        if (selectedChannel is null) return;

        var newMessage = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages = [..messages, newMessage];
    }

    private async Task HandleOpenThread(int rootMessageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void HandleCloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task HandleSendReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies = [..threadReplies, reply];

        // Update thread summary count
        BuildThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh the messages/thread to show updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
        }

        if (threadRootMessage is not null)
        {
            threadReplies = await ChatService.GetThreadAsync(threadRootMessage.Id);
            threadRootMessage = messages.FirstOrDefault(m => m.Id == threadRootMessage.Id) ?? threadRootMessage;
        }
    }

    private void BuildThreadSummaries()
    {
        // Build thread summaries from messages that have replies
        var rootIds = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        threadSummaries = rootIds;
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #dcddde;
    background-color: #313338;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 300px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
}

.chat-main.full-width {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

